import React from 'react'
import type {
  ResourcesSections,
  SectionsShown,
  PermissionsState,
  SectionName,
} from '../types/integration-permission-selector'

interface HiddenPermissionInputsProps {
  resources: ResourcesSections
  showSections: SectionsShown
  permissionsSelected: PermissionsState
}

const actionLabels = {
  none: 'No access',
  read: 'Read-only',
  write: 'Read and write',
  admin: 'Admin',
}

const sectionToShownKey: Record<SectionName, keyof SectionsShown> = {
  repository: 'repository',
  organization: 'organization',
  user: 'user',
  business: 'enterprise',
}

export function HiddenPermissionInputs({resources, showSections, permissionsSelected}: HiddenPermissionInputsProps) {
  const inputs: React.ReactElement[] = []

  for (const [section, sectionResources] of Object.entries(resources)) {
    const sectionName = section as SectionName
    const shownKey = sectionToShownKey[sectionName]
    const isVisible = sectionName === 'repository' || showSections?.[shownKey]

    for (const resource of sectionResources ?? []) {
      const permissionName = resource.name
      const permissionTitle = resource.metadata.title

      let actionKey = 'none'
      if (isVisible) {
        const selectedAction = permissionsSelected[sectionName][permissionTitle] || 'No access'
        actionKey = Object.entries(actionLabels).find(([, label]) => label === selectedAction)?.[0] || 'none'
      }

      inputs.push(
        <input
          key={`${section}-${permissionName}`}
          type="hidden"
          name={`integration[default_permissions][${permissionName}]`}
          value={actionKey}
          data-testid={`hidden-input-${permissionName}`}
        />,
      )
    }
  }

  return <>{inputs}</>
}

try{ HiddenPermissionInputs.displayName ||= 'HiddenPermissionInputs' } catch {}