import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {SelectPanel, Button, type SelectPanelItemInput} from '@primer/react'
import type {
  SectionsShown,
  SectionName,
  ResourcesSections,
  PermissionsState,
  SectionPermissions,
} from '../types/integration-permission-selector'
import {useMemo, useState, type Dispatch, type SetStateAction} from 'react'
import {testIdProps} from '@github-ui/test-id-props'
import {PlusIcon} from '@primer/octicons-react'
import {PermissionSelectorTab} from './PermissionSelectorTab'

export interface PermissionSelectorBarProps {
  sections: SectionsShown
  permissionsSelected: PermissionsState
  setPermissionsSelected: Dispatch<SetStateAction<PermissionsState>>
  tabSelected: SectionName
  tabOnClick: Dispatch<SetStateAction<SectionName>>
  resources: ResourcesSections
  requireMetadata?: boolean
  listViewSize?: 'xs' | 'sm' | 'lg'
}

const permissionSections: Array<{key: SectionName; title: string}> = [
  {
    key: 'repository',
    title: 'Repositories',
  },
  {
    key: 'business',
    title: 'Enterprise',
  },
  {
    key: 'organization',
    title: 'Organizations',
  },
  {
    key: 'user',
    title: 'Account',
  },
]

function updatedSectionPermissions(
  items: SelectPanelItemInput[],
  sectionSelected: SectionName,
  previousState: PermissionsState,
  resources: ResourcesSections,
): SectionPermissions {
  const updated: SectionPermissions = {}

  for (const item of items) {
    if (item.text) {
      const prevAction = previousState[sectionSelected][item.text]
      const defaultAction =
        resources[sectionSelected].find(p => p.metadata.title === item.text)?.metadata.fgp?.[0] ?? 'Read'
      updated[item.text] = prevAction ?? defaultAction
    }
  }

  return updated
}

function permissionSelectionHandler(
  sectionSelected: SectionName,
  resources: ResourcesSections,
  setPermissionsSelected: Dispatch<SetStateAction<PermissionsState>>,
) {
  return (items: SelectPanelItemInput[]) => {
    setPermissionsSelected(prev => ({
      ...prev,
      [sectionSelected]: updatedSectionPermissions(items, sectionSelected, prev, resources),
    }))
  }
}

export function PermissionSelectorBar({
  sections,
  permissionsSelected,
  setPermissionsSelected,
  tabSelected,
  tabOnClick,
  resources,
  requireMetadata,
  listViewSize,
}: PermissionSelectorBarProps) {
  const panelTitle = tabSelected === 'user' ? 'Select account permissions' : `Select ${tabSelected} permissions`

  const permissionLists = useMemo(
    () => ({
      repository: resources.repository.map(permission => {
        return {
          id: permission.metadata.title,
          text: permission.metadata.title,
          disabled: requireMetadata && permission.metadata.title === 'Metadata',
        }
      }),
      business: resources.business.map(permission => ({
        id: permission.metadata.title,
        text: permission.metadata.title,
      })),
      user: resources.user.map(permission => ({
        id: permission.metadata.title,
        text: permission.metadata.title,
      })),
      organization: resources.organization.map(permission => ({
        id: permission.metadata.title,
        text: permission.metadata.title,
      })),
    }),
    [resources, requireMetadata],
  )

  const [filters, setFilters] = useState<{
    repository: string
    business: string
    user: string
    organization: string
  }>({
    repository: '',
    business: '',
    user: '',
    organization: '',
  })

  const filteredSectionsItems = {
    repository: permissionLists.repository.filter(
      item => item.text?.toLowerCase().includes(filters.repository.toLowerCase()),
    ),
    business: permissionLists.business.filter(
      item => item.text?.toLowerCase().includes(filters.business.toLowerCase()),
    ),
    user: permissionLists.user.filter(item => item.text?.toLowerCase().includes(filters.user.toLowerCase())),
    organization: permissionLists.organization.filter(
      item => item.text?.toLowerCase().includes(filters.organization.toLowerCase()),
    ),
  }

  function getPermissionPanelProps(sectionSelected: SectionName) {
    return {
      filteredPermissions: filteredSectionsItems[sectionSelected] ?? [],
      selectedPermissions: permissionLists[sectionSelected].filter(item =>
        Object.keys(permissionsSelected[sectionSelected]).includes(item.text),
      ),
      setSelectedPermissions: permissionSelectionHandler(sectionSelected, resources, setPermissionsSelected),
      setFilterPermissions: (value: string) =>
        setFilters(prev => ({
          ...prev,
          [sectionSelected]: value,
        })),
    }
  }

  const [openPanel, setOpenPanel] = useState(false)

  const {filteredPermissions, selectedPermissions, setSelectedPermissions, setFilterPermissions} =
    getPermissionPanelProps(tabSelected)

  const visibleTabsCount = useMemo(() => {
    return permissionSections.filter(section => sections[section.key as keyof SectionsShown]).length
  }, [sections])

  const showAddPermissionsText = listViewSize !== 'xs' && !(listViewSize === 'sm' && visibleTabsCount > 2)

  return (
    <ListViewMetadata
      sectionFilters={
        <div className="d-flex flex-col" {...testIdProps('permission-bar')}>
          {permissionSections.map(section => {
            if (!sections[section.key as keyof SectionsShown]) return null
            return (
              <div
                className="d-flex flex-row align-items-center"
                key={section.key}
                {...testIdProps('permission-filter-link')}
              >
                <PermissionSelectorTab
                  title={section.title}
                  isSelected={tabSelected === section.key}
                  count={Object.keys(permissionsSelected[section.key]).length}
                  onClick={e => {
                    e.preventDefault()
                    tabOnClick(section.key)
                  }}
                />
              </div>
            )
          })}
        </div>
      }
    >
      <SelectPanel
        title={panelTitle}
        renderAnchor={({children, ...anchorProps}) => (
          <Button
            {...anchorProps}
            aria-haspopup="dialog"
            style={{
              ...(!showAddPermissionsText && {padding: '8px', width: '32px', height: '32px'}),
            }}
          >
            <PlusIcon size={16} className={showAddPermissionsText ? 'pr-4' : ''} {...testIdProps('plus-icon')} />
            {showAddPermissionsText && <span>Add permissions</span>}
          </Button>
        )}
        placeholder="Add permissions"
        placeholderText="Search"
        open={openPanel}
        onOpenChange={setOpenPanel}
        overlayProps={{maxHeight: 'medium', anchorSide: 'outside-bottom', width: 'medium'}}
        items={filteredPermissions}
        selected={selectedPermissions}
        onSelectedChange={setSelectedPermissions}
        onFilterChange={setFilterPermissions}
      />
    </ListViewMetadata>
  )
}

try{ PermissionSelectorBar.displayName ||= 'PermissionSelectorBar' } catch {}